// Tests for headers generated by tools/gen_api.
#include <gtest/gtest.h>

#include "vpp/api/interface.api.h"
#include "vpp/api/ip.api.h"
#include "vpp/api/memclnt.api.h"
#include "vpp/api/vpe.api.h"
#include "vpp/rpc.h"

namespace vpp {
namespace {

TEST(GeneratedApiTest, MessageNamesCarryCrc) {
  EXPECT_STREQ(api::ControlPing::kName, "control_ping_51077d14");
  EXPECT_STREQ(api::ShowVersionReply::kName, "show_version_reply_c919bde1");
  static_assert(std::is_same<api::ShowVersion::Reply, api::ShowVersionReply>::value,
                "service reply alias");
}

TEST(GeneratedApiTest, ReplyRoundTrip) {
  api::ShowVersionReply in;
  in.retval = -3;
  in.program = "vpe";
  in.build_directory = "/b";
  Encoder e;
  in.Encode(e);
  EXPECT_EQ(e.bytes().size(), 4u + 32 + 32 + 32 + 256);

  api::ShowVersionReply out;
  Decoder d(e.bytes());
  out.Decode(d);
  EXPECT_TRUE(d.ok());
  EXPECT_EQ(out.retval, -3);
  EXPECT_EQ(out.program, "vpe");
  EXPECT_EQ(out.build_directory, "/b");
}

TEST(GeneratedApiTest, EnumsAliasesAndNestedTypes) {
  api::IpRouteLookup unused;
  (void)unused;
  api::Prefix p;
  p.address.af = api::AddressFamily::ADDRESS_IP6;
  p.address.un.raw[15] = 1;
  p.len = 128;
  Encoder e;
  p.Encode(e);
  ASSERT_EQ(e.bytes().size(), 1u + 16 + 1);
  EXPECT_EQ(e.bytes()[0], 1);
  api::Prefix q;
  Decoder d(e.bytes());
  q.Decode(d);
  EXPECT_TRUE(d.ok());
  EXPECT_EQ(q.address.af, api::AddressFamily::ADDRESS_IP6);
  EXPECT_EQ(q.len, 128);
}

TEST(GeneratedApiTest, VariableArrayCountDerivedFromVector) {
  api::SwInterfaceSetRxMode unused;
  (void)unused;
  api::IpAddressDump d1;
  (void)d1;
  // sw_interface_set_unnumbered etc. are covered by compilation; here we
  // check a message with a counted array.
  api::IpRouteAddDel r;
  r.route.paths.resize(2);
  Encoder e;
  r.Encode(e);
  api::IpRouteAddDel back;
  Decoder d(e.bytes());
  back.Decode(d);
  EXPECT_TRUE(d.ok());
  EXPECT_EQ(back.route.n_paths, 2);
  EXPECT_EQ(back.route.paths.size(), 2u);
}

TEST(GeneratedApiTest, TruncatedDecodeFails) {
  api::ShowVersionReply out;
  std::vector<uint8_t> shortbuf(3);
  Decoder d(shortbuf);
  out.Decode(d);
  EXPECT_FALSE(d.ok());
}

}  // namespace
}  // namespace vpp
